use std::{
    collections::HashSet,
    fmt::Write as _,
    fs,
    io::{self, BufRead, IsTerminal, Stdout, Write},
    path::Path,
    process::Command,
};

use anyhow::{Context, Result, bail};
use serde::Deserialize;

use crate::{
    colors::ColorSpec,
    scheme::{self, LIBRARY_DIR, LIBRARY_REPO},
};

/// JSON export of WezTerm's built-in schemes, generated by its `sync-color-schemes` tool.
const DATA_URL: &str = "https://raw.githubusercontent.com/wezterm/wezterm/main/docs/colorschemes/data.json";
/// The export is ~0.9 MB; refuse anything absurdly larger.
const MAX_DOWNLOAD_BYTES: &str = "16000000";
const PART_FILE: &str = "data.json.part";

const ANSI_NAMES: [&str; 8] = ["black", "red", "green", "yellow", "blue", "magenta", "cyan", "white"];

/// One entry of WezTerm's `data.json`. Only the fields term-boss can apply are read.
#[derive(Deserialize)]
struct Entry {
    colors: WezColors,
    metadata: WezMeta,
}

#[derive(Deserialize)]
struct WezColors {
    #[serde(default)]
    ansi: Vec<String>,
    #[serde(default)]
    brights: Vec<String>,
    foreground: Option<String>,
    background: Option<String>,
    cursor_bg: Option<String>,
}

#[derive(Deserialize)]
struct WezMeta {
    name: String,
    #[serde(default)]
    aliases: Option<Vec<String>>,
    author: Option<String>,
    origin_url: Option<String>,
}

/// Download WezTerm's colour scheme collection and convert it to Alacritty-format files in
/// `<config_dir>/wezterm_schemes/`.
///
/// This is the only place term-boss ever touches the network, and it runs only when the user
/// invokes it. Every colour is parsed before it is written, so the generated files contain
/// nothing but normalised `#rrggbb` values and comment text with control characters removed.
pub fn install(stdout: &mut Stdout, yes: bool) -> Result<()> {
    let config_dir = scheme::config_dir()?;
    let dir = scheme::library_dir()?;
    let updating = dir.is_dir();

    writeln!(
        stdout,
        "This downloads WezTerm's built-in colour scheme collection ({LIBRARY_REPO})\n  {DATA_URL}\n\
         and converts it to the format term-boss uses in\n  {}\n\
         (about 1000 schemes, under 1 MB). Rerun this command to update.\n\
         term-boss never touches the network outside this command.",
        dir.display()
    )?;

    if !yes && !updating {
        if !io::stdin().is_terminal() {
            bail!("stdin is not a terminal; rerun interactively or pass --yes");
        }
        write!(stdout, "Download now? [y/N] ")?;
        stdout.flush()?;
        let mut answer = String::new();
        io::stdin().lock().read_line(&mut answer)?;
        if !matches!(answer.trim().to_ascii_lowercase().as_str(), "y" | "yes") {
            writeln!(stdout, "Skipped.")?;
            return Ok(());
        }
    }

    fs::create_dir_all(&config_dir).with_context(|| format!("unable to create {}", config_dir.display()))?;
    let part = config_dir.join(PART_FILE);
    let _ = fs::remove_file(&part);
    download(&part)?;
    let data = fs::read_to_string(&part).with_context(|| format!("unable to read {}", part.display()))?;
    let entries: Vec<Entry> =
        serde_json::from_str(&data).context("the downloaded colour scheme data is not in the expected format")?;
    if entries.is_empty() {
        bail!("the downloaded colour scheme data contains no schemes");
    }

    let tmp = config_dir.join(format!("{LIBRARY_DIR}.tmp"));
    if tmp.exists() {
        fs::remove_dir_all(&tmp).with_context(|| format!("unable to remove {}", tmp.display()))?;
    }
    fs::create_dir_all(&tmp).with_context(|| format!("unable to create {}", tmp.display()))?;

    let real_names: HashSet<&str> = entries.iter().map(|e| e.metadata.name.as_str()).collect();
    let mut written: HashSet<String> = HashSet::new();
    let mut aliases = 0usize;
    let mut skipped_colors = 0usize;
    let mut skipped_names: Vec<String> = Vec::new();

    for entry in &entries {
        let name = &entry.metadata.name;
        let (toml, skipped) = convert(entry, None);
        skipped_colors += skipped;
        match write_scheme(&tmp, name, &toml) {
            Ok(()) => {
                written.insert(name.clone());
            }
            Err(_) => skipped_names.push(name.clone()),
        }
        for alias in entry.metadata.aliases.iter().flatten() {
            if real_names.contains(alias.as_str()) || written.contains(alias) {
                continue;
            }
            let (toml, _) = convert(entry, Some(alias));
            match write_scheme(&tmp, alias, &toml) {
                Ok(()) => {
                    written.insert(alias.clone());
                    aliases += 1;
                }
                Err(_) => skipped_names.push(alias.clone()),
            }
        }
    }

    if dir.exists() {
        fs::remove_dir_all(&dir).with_context(|| format!("unable to remove {}", dir.display()))?;
    }
    fs::rename(&tmp, &dir).with_context(|| format!("unable to move {} to {}", tmp.display(), dir.display()))?;
    let _ = fs::remove_file(&part);

    let own = config_dir.join(scheme::SCHEME_DIR);
    writeln!(
        stdout,
        "{} colour schemes written to {} ({aliases} of them aliases; {skipped_colors} unusable colour values skipped).",
        written.len(),
        dir.display()
    )?;
    if !skipped_names.is_empty() {
        writeln!(stdout, "Skipped {} scheme(s) with unsafe names: {}", skipped_names.len(), skipped_names.join(", "))?;
    }
    writeln!(
        stdout,
        "Names match wezterm's `color_scheme` setting. Select one with `scheme = \"Dracula (Official)\"` in a \
         .term-boss.toml or `term-boss set --scheme \"Dracula (Official)\"`.\nFiles in {} take precedence over the library.",
        own.display()
    )?;
    Ok(())
}

/// Fetch `DATA_URL` to `dest` with curl: HTTPS only, bounded time and size, fail on HTTP errors.
fn download(dest: &Path) -> Result<()> {
    let status = Command::new("curl")
        .args(["-fsSL", "--proto", "=https", "--max-time", "60", "--max-filesize", MAX_DOWNLOAD_BYTES, "-o"])
        .arg(dest)
        .arg(DATA_URL)
        .status()
        .context("unable to run curl; is it installed and on PATH?")?;
    if !status.success() {
        bail!("downloading {DATA_URL} failed ({status})");
    }
    Ok(())
}

fn write_scheme(dir: &Path, name: &str, toml: &str) -> Result<()> {
    scheme::validate_name(name)?;
    let path = dir.join(format!("{name}.toml"));
    fs::write(&path, toml).with_context(|| format!("unable to write {}", path.display()))
}

/// Comment-safe text: no control characters, so a value can never end the comment line.
fn comment_text(s: &str) -> String {
    s.chars().filter(|c| !c.is_control()).collect()
}

/// Parse a WezTerm colour string and re-emit it as `#rrggbb`; `None` (counted) if unparsable.
fn hex(value: &str, skipped: &mut usize) -> Option<String> {
    match value.parse::<ColorSpec>() {
        Ok(color) => Some(format!("#{color:x}")),
        Err(_) => {
            *skipped += 1;
            None
        }
    }
}

/// Render one entry as an Alacritty-format scheme. Returns the TOML and the number of colour
/// values that could not be parsed.
fn convert(entry: &Entry, alias: Option<&str>) -> (String, usize) {
    let mut skipped = 0;
    let mut out = String::new();
    let name = comment_text(&entry.metadata.name);
    match alias {
        Some(alias) => {
            let _ = writeln!(out, "# {}\n# Alias of {name}", comment_text(alias));
        }
        None => {
            let _ = writeln!(out, "# {name}");
        }
    }
    if let Some(author) = &entry.metadata.author {
        let _ = writeln!(out, "# Author: {}", comment_text(author));
    }
    if let Some(origin) = &entry.metadata.origin_url {
        let _ = writeln!(out, "# Origin: {}", comment_text(origin));
    }
    let _ = writeln!(out, "# Converted from WezTerm's colour scheme data ({LIBRARY_REPO}) by `term-boss setup colorschemes`.");

    let colors = &entry.colors;
    let background = colors.background.as_deref().and_then(|v| hex(v, &mut skipped));
    let foreground = colors.foreground.as_deref().and_then(|v| hex(v, &mut skipped));
    if background.is_some() || foreground.is_some() {
        let _ = writeln!(out, "\n[colors.primary]");
        if let Some(bg) = background {
            let _ = writeln!(out, "background = \"{bg}\"");
        }
        if let Some(fg) = foreground {
            let _ = writeln!(out, "foreground = \"{fg}\"");
        }
    }
    if let Some(cursor) = colors.cursor_bg.as_deref().and_then(|v| hex(v, &mut skipped)) {
        let _ = writeln!(out, "\n[colors.cursor]\ncursor = \"{cursor}\"");
    }
    for (section, values) in [("normal", &colors.ansi), ("bright", &colors.brights)] {
        let slots: Vec<(&str, String)> = ANSI_NAMES
            .iter()
            .zip(values)
            .filter_map(|(slot, value)| hex(value, &mut skipped).map(|h| (*slot, h)))
            .collect();
        if slots.is_empty() {
            continue;
        }
        let _ = writeln!(out, "\n[colors.{section}]");
        for (slot, value) in slots {
            let _ = writeln!(out, "{slot} = \"{value}\"");
        }
    }
    (out, skipped)
}
